/**
 * A runtime-validation schema library, declared the way the real ones are: a
 * schema value exposes `parse`, whose return type is the validated output, and
 * optional members are marked on the schema so the object output carries `?`.
 */

export interface Schema<Output> {
  parse(data: unknown): Output;
  readonly _output: Output;
}

export interface OptionalSchema<Output> extends Schema<Output | undefined> {
  readonly __optional: true;
}

type OutputOf<S> = S extends Schema<infer Output> ? Output : never;

type OptionalKeys<Shape> = {
  [K in keyof Shape]: Shape[K] extends OptionalSchema<unknown> ? K : never;
}[keyof Shape];

type RequiredKeys<Shape> = Exclude<keyof Shape, OptionalKeys<Shape>>;

/** Homomorphic, so the `?` modifiers survive the flattening. */
type Flatten<T> = { [K in keyof T]: T[K] };

type ObjectOutput<Shape extends Record<string, Schema<unknown>>> = Flatten<
  { [K in RequiredKeys<Shape>]: OutputOf<Shape[K]> } & {
    [K in OptionalKeys<Shape>]?: OutputOf<Shape[K]>;
  }
>;

export declare function object<Shape extends Record<string, Schema<unknown>>>(
  shape: Shape
): Schema<ObjectOutput<Shape>>;
export declare function string(): Schema<string>;
export declare function number(): Schema<number>;
export declare function array<Item extends Schema<unknown>>(
  item: Item
): Schema<OutputOf<Item>[]>;
export declare function optional<Inner extends Schema<unknown>>(
  inner: Inner
): OptionalSchema<OutputOf<Inner>>;
